const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'P(-3,2)' },
      { kind: 'text', payload: '第二象限' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: 'y' },
      { kind: 'text', payload: 'O' },
      { kind: 'text', payload: '-3' },
      { kind: 'text', payload: '2' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var ox = W * 0.5;
    var oy = H * 0.58;
    var S = Math.min(W, H) * 0.075;
    var px = ox - 3 * S;
    var py = oy - 2 * S;
    var xStart = W * 0.06;
    var xEnd = W * 0.92;
    var yTop = H * 0.07;
    var yBot = H * 0.95;
    var ah = Math.min(W, H) * 0.02;

    var cmds = {
      axisX: [['M', xStart, oy], ['L', xEnd, oy]],
      headX: [['M', xEnd, oy], ['L', xEnd - ah * 2, oy - ah], ['L', xEnd - ah * 2, oy + ah], ['Z']],
      axisY: [['M', ox, yBot], ['L', ox, yTop]],
      headY: [['M', ox, yTop], ['L', ox - ah, yTop + ah * 2], ['L', ox + ah, yTop + ah * 2], ['Z']],
      tickX: [['M', px, oy - ah], ['L', px, oy + ah]],
      tickY: [['M', ox - ah, py], ['L', ox + ah, py]],
      dashV: [['M', px, py], ['L', px, oy]],
      dashH: [['M', px, py], ['L', ox, py]],
      pt: visualSdk.circle(px, py, Math.min(W, H) * 0.012)
    };

    var ids = ['axisX', 'headX', 'axisY', 'headY', 'tickX', 'tickY', 'dashV', 'dashH', 'pt'];
    var paths = [];
    var i;
    for (i = 0; i < ids.length; i++) {
      paths.push({ id: ids[i], commands: cmds[ids[i]] });
    }

    var children = [
      { type: 'path', pathId: 'axisX', fill: '#26354a', stroke: { width: 2 } },
      { type: 'path', pathId: 'headX', fill: '#26354a' },
      { type: 'path', pathId: 'axisY', fill: '#26354a', stroke: { width: 2 } },
      { type: 'path', pathId: 'headY', fill: '#26354a' },
      { type: 'path', pathId: 'tickX', fill: '#26354a', stroke: { width: 2 } },
      { type: 'path', pathId: 'tickY', fill: '#26354a', stroke: { width: 2 } },
      { type: 'path', pathId: 'dashV', fill: '#26354a', stroke: { width: 2, dash: [7, 5] } },
      { type: 'path', pathId: 'dashH', fill: '#26354a', stroke: { width: 2, dash: [7, 5] } },
      { type: 'path', pathId: 'pt', fill: '#26354a' },
      { type: 'label', contentId: metrics[0].contentId, anchor: { x: px - 8, y: py - 8 }, hAlign: 'right', vAlign: 'bottom', color: '#26354a' },
      { type: 'label', contentId: metrics[1].contentId, anchor: { x: ox - W * 0.30, y: oy - H * 0.30 }, hAlign: 'center', vAlign: 'middle', color: '#26354a' },
      { type: 'label', contentId: metrics[2].contentId, anchor: { x: xEnd - 4, y: oy + 14 }, hAlign: 'right', vAlign: 'top', color: '#26354a' },
      { type: 'label', contentId: metrics[3].contentId, anchor: { x: ox + 12, y: yTop + 4 }, hAlign: 'left', vAlign: 'top', color: '#26354a' },
      { type: 'label', contentId: metrics[4].contentId, anchor: { x: ox - 10, y: oy + 10 }, hAlign: 'right', vAlign: 'top', color: '#26354a' },
      { type: 'label', contentId: metrics[5].contentId, anchor: { x: px, y: oy + 12 }, hAlign: 'center', vAlign: 'top', color: '#26354a' },
      { type: 'label', contentId: metrics[6].contentId, anchor: { x: ox - 10, y: py }, hAlign: 'right', vAlign: 'middle', color: '#26354a' }
    ];

    return {
      schemaVersion: 1,
      sceneId: 'fig-point-P-second-quadrant',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
